actions.script:
// nothing to do where Customer Service is not configured (no ServicePolicy) or for a case already
const configured = ec.entity.find('mantle.request.support.ServicePolicy').disableAuthz().count() > 0
if (!configured || ec.entity.find('mantle.request.support.CaseProfile').condition('requestId', requestId).disableAuthz().count() > 0) return
ec.message.pushErrors()
try {
    let queued = false
    try {
        ec.service.special().name('mantle.request.SupportCaseServices.ensure#CaseProfile').parameters({requestId: requestId}).registerOnCommit()
        queued = true
    } catch (err) { queued = false }
    if (!queued) ec.service.sync().name('mantle.request.SupportCaseServices.ensure#CaseProfile').parameters({requestId: requestId}).disableAuthz().call()
} catch (err) {
    ec.logger.error(`Request ${requestId}: the case rule was not queued: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

if (!(ec.entity.find('mantle.request.support.CaseProfile').condition('requestId', requestId).disableAuthz().count() > 0)) return
ec.message.pushErrors()
try {
    ec.resource.script('component://mr-mantle/service/mantle/request/SupportCases.js').execute('customerReply', context)
} catch (err) {
    ec.logger.error(`Case ${requestId}: the customer reply notice was not sent: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
